    routes = []

    # Sort customers by demand to try to pack them into fewer vehicles
    sorted_customers = sorted(instance.customer_ids, key=lambda cid: instance.node_map[cid].demand, reverse=True)

    for cid in sorted_customers:
        route = [depot, cid, depot]
        states = propagate_route(instance, route)

        # Check if the route is battery-feasible
        if all(state.battery_arrival >= 0 for state in states):
            routes.append(route)
            continue

        # If not battery-feasible, insert a charging station
        best_route = None
        best_states = None
        for station_id in instance.station_ids:
            for i in range(1, len(route)):
                new_route = route[:i] + [station_id] + route[i:]
                new_states = propagate_route(instance, new_route)

                if all(state.battery_arrival >= 0 for state in new_states):
                    if best_route is None or calculate_total_distance(instance, [new_route]) < calculate_total_distance(instance, [best_route]):
                        best_route = new_route
                        best_states = new_states
                    break
            else:
                continue
            break

        if best_route is not None:
            routes.append(best_route)
        else:
            # If no feasible charging station is found, use the original route with the highest battery drain
            max_drain = max(state.battery_departure - state.battery_arrival for state in states)
            for i in range(1, len(route)):
                new_route = route[:i] + [depot] + route[i:]
                new_states = propagate_route(instance, new_route)
                if all(state.battery_arrival >= 0 for state in new_states) and max_drain < max(state.battery_departure - state.battery_arrival for state in new_states):
                    routes.append(new_route)
                    break
            else:
                routes.append(route)

    # Try to merge routes to minimize the number of vehicles
    merged_routes = []
    for route in routes:
        merged = False
        for i, merged_route in enumerate(merged_routes):
            new_route = merged_route + route[1:]  # Try appending the current route to an existing one
            new_states = propagate_route(instance, new_route)

            if all(state.battery_arrival >= 0 for state in new_states):
                merged_routes[i] = new_route
                merged = True
                break
        if not merged:
            merged_routes.append(route)

    # Sort merged routes by total distance
    merged_routes.sort(key=lambda route: calculate_total_distance(instance, [route]))

    # Further attempt to reduce the number of vehicles by reassigning customers
    # to existing routes if possible
    final_routes = []
    for route in merged_routes:
        assigned = False
        for i, final_route in enumerate(final_routes):
            if can_merge_routes(instance, final_route, route):
                final_routes[i] = merge_routes(instance, final_route, route)
                assigned = True
