def find_best_charging_station(instance, route):
    best_station = None
    best_energy_charged = 0
    for station_id in instance.station_ids:
        new_route = route[:1] + [station_id] + route[1:]
        states = propagate_route(instance, new_route)
        if all(state.battery_arrival >= 0 for state in states):
            energy_charged = sum(state.energy_charged for state in states)
            if energy_charged > best_energy_charged:
                best_energy_charged = energy_charged
                best_station = station_id
    return best_station

